@@ -1,3 +1,73 @@
+const FORBIDDEN_KEYS = new Set(["__proto__", "prototype", "constructor"]);
+
+function isPlainObject(value) {
+  if (typeof value !== "object" || value === null) return false;
+  const proto = Object.getPrototypeOf(value);
+  return proto === null || proto === Object.prototype;
+}
+
+function deepClone(value) {
+  if (value === null || typeof value !== "object") return value;
+
+  if (Array.isArray(value)) {
+    return value.map(deepClone);
+  }
+
+  if (value instanceof Date) {
+    return new Date(value.getTime());
+  }
+
+  if (value instanceof RegExp) {
+    return new RegExp(value.source, value.flags);
+  }
+
+  if (value instanceof Map) {
+    const clone = new Map();
+    for (const [k, v] of value) {
+      clone.set(deepClone(k), deepClone(v));
+    }
+    return clone;
+  }
+
+  if (value instanceof Set) {
+    const clone = new Set();
+    for (const v of value) {
+      clone.add(deepClone(v));
+    }
+    return clone;
+  }
+
+  const proto = Object.getPrototypeOf(value);
+  const clone = Object.create(proto);
+  for (const key of Object.keys(value)) {
+    if (FORBIDDEN_KEYS.has(key)) continue;
+    clone[key] = deepClone(value[key]);
+  }
+  return clone;
+}
+
 export function safeMerge(base, patch) {
-  return { ...base, ...patch };
+  const baseKeys = isPlainObject(base) ? Object.keys(base) : [];
+  const patchKeys = isPlainObject(patch) ? Object.keys(patch) : [];
+  const keys = new Set([...baseKeys, ...patchKeys]);
+
+  const result = {};
+  for (const key of keys) {
+    if (FORBIDDEN_KEYS.has(key)) continue;
+
+    const hasPatch = Object.prototype.hasOwnProperty.call(patch, key);
+    if (!hasPatch) {
+      result[key] = deepClone(base[key]);
+      continue;
+    }
+
+    const baseVal = base[key];
+    const patchVal = patch[key];
+    if (isPlainObject(baseVal) && isPlainObject(patchVal)) {
+      result[key] = safeMerge(baseVal, patchVal);
+    } else {
+      result[key] = deepClone(patchVal);
+    }
+  }
+  return result;
 }
